#!/bin/sh
# Genera index.html a partir del juego (game.src.html, el mismo archivo que el boceto de Claude)
{ printf '<!doctype html>\n<html lang="es">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover">\n<meta name="robots" content="noindex">\n<meta name="theme-color" content="#0b0816">\n<title>Noche en el Cementerio</title>\n<link rel="icon" type="image/png" href="favicon-32.png?v=3">\n<link rel="apple-touch-icon" href="apple-touch-icon.png?v=3">\n<link rel="manifest" href="manifest.webmanifest?v=3">\n<meta name="apple-mobile-web-app-capable" content="yes">\n<meta name="mobile-web-app-capable" content="yes">\n<meta name="apple-mobile-web-app-title" content="Cementerio">\n<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">\n<script src="config.js"></script>\n<style>:root{padding-top:env(safe-area-inset-top);padding-bottom:env(safe-area-inset-bottom)}html,body{margin:0;height:100%%}[hidden]{display:none!important}</style>\n</head>\n<body>\n'; cat game.src.html; printf '\n</body>\n</html>\n'; } > index.html
